<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Jobs\Dezerx\InstallWorld; use Pterodactyl\Services\Dezerx\Catalogue\WorldCatalogue; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Worlds\WorldRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Worlds\WorldInstallRequest; class WorldController extends ClientApiController { public function catalogue(WorldRequest $request, Server $server, WorldCatalogue $catalogue): JsonResponse { return new JsonResponse([ 'available' => $catalogue->available(), 'categories' => $catalogue->categories(), ]); } public function search(WorldRequest $request, Server $server, WorldCatalogue $catalogue): JsonResponse { $data = $request->validate([ 'query' => ['nullable', 'string', 'max:120'], 'page' => ['nullable', 'integer', 'min:1', 'max:500'], 'category' => ['nullable', 'integer'], 'sort' => ['nullable', 'string', 'in:popular,updated,downloads,name'], ]); return new JsonResponse($catalogue->search( (string) ($data['query'] ?? ''), (int) ($data['page'] ?? 1), isset($data['category']) ? (int) $data['category'] : null, (string) ($data['sort'] ?? 'popular'), )); } public function files(WorldRequest $request, Server $server, WorldCatalogue $catalogue): JsonResponse { $data = $request->validate(['id' => ['required', 'string', 'max:32']]); return new JsonResponse(['files' => $catalogue->files($data['id'])]); } public function install(WorldInstallRequest $request, Server $server, WorldCatalogue $catalogue): JsonResponse { $data = $request->validate([ 'id' => ['required', 'string', 'max:32'], 'fileId' => ['nullable', 'string', 'max:32'], 'name' => ['nullable', 'string', 'max:64'], 'activate' => ['nullable', 'boolean'], ]); $running = InstallWorld::status($server->uuid); if (in_array($running['state'] ?? 'idle', ['downloading', 'unpacking', 'placing'], true)) { return $this->refuse('A world is already being installed on this server. Wait for it to finish.', 409); } $download = $catalogue->download($data['id'], (string) ($data['fileId'] ?? '')); if ($download === null) { return $this->refuse( 'That download could not be resolved. The author may have opted out of downloads outside CurseForge, in which case the map has to be uploaded by hand.', 422, ); } $name = $this->folderName((string) ($data['name'] ?? ''), $download['filename']); if ($name === null) { return $this->refuse('That is not a usable folder name.', 422); } InstallWorld::queued($server->uuid, $download['filename']); InstallWorld::dispatch($server, $download['url'], $download['filename'], $name, (bool) ($data['activate'] ?? false)); return new JsonResponse([ 'state' => 'downloading', 'message' => "Fetching {$download['filename']}.", 'file' => $download['filename'], 'name' => $name, ], 202); } public function status(WorldRequest $request, Server $server): JsonResponse { return new JsonResponse(InstallWorld::status($server->uuid)); } private function folderName(string $asked, string $filename): ?string { $base = $asked !== '' ? $asked : preg_replace('/\.zip$/i', '', $filename); $base = preg_replace('/[^A-Za-z0-9._-]+/', '-', (string) $base) ?? ''; $base = trim($base, '-._'); $base = mb_substr($base, 0, 48); return $base === '' ? null : $base; } private function refuse(string $message, int $status): JsonResponse { return new JsonResponse([ 'errors' => [['code' => 'WorldActionRefused', 'status' => (string) $status, 'detail' => $message]], ], $status); } } 